def backfill_legacy_orders(apps, schema_editor):
    """Orders placed before the marketplace ledger existed: no commission applied (they predate the
    policy), snapshots equal the list values, REFUND_DUE becomes REFUND_PENDING."""
    from django.db.models import F

    Order = apps.get_model("commerce", "Order")
    OrderItem = apps.get_model("commerce", "OrderItem")
    OrderItem.objects.update(
        merchandise_net=F("line_total"), buyer_paid=F("line_total"), seller_payable=F("line_total")
    )
    Order.objects.update(
        list_total=F("total"), merchandise_net=F("total"), seller_payable_total=F("total")
    )
    Order.objects.filter(payment_status="REFUND_DUE").update(payment_status="REFUND_PENDING")


